function useSaved(key, initial) {
  const [value, setValue] = useState(() => { try { return migrateStoredStudios(key, JSON.parse(localStorage.getItem('fg-hub-' + key)) ?? initial); } catch { return initial; } });
  useEffect(() => { try { localStorage.setItem('fg-hub-' + key, JSON.stringify(value)); } catch { /* Private browser mode may disable persistence. */ } }, [key, value]);
  useEffect(() => { const update = event => { if (event.key !== 'fg-hub-' + key || event.newValue === null) return; try { setValue(migrateStoredStudios(key, JSON.parse(event.newValue))); } catch {} }; window.addEventListener('storage', update); return () => window.removeEventListener('storage', update); }, [key]);
  return [value, setValue];
}
function fileStore(mode, action) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('fg-hub-files', 1);
    request.onupgradeneeded = () => request.result.createObjectStore('files');
    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const db = request.result;
      const tx = db.transaction('files', mode);
      const op = action(tx.objectStore('files'));
      let result;
      op.onsuccess = () => { result = op.result; };
      tx.oncomplete = () => { db.close(); resolve(result); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    };
  });
}
