        await fileStore('readwrite', store => store.put(file, id));
        const isText = /\.(txt|md|csv)$/i.test(file.name);
        const content = isText ? (await file.text()).slice(0, 60000) : '';
        setDocs(current => [...current, { id, title: file.name, category: 'Neue Dateien', type: file.name.split('.').pop().toUpperCase(), studio, date: today, size: `${(file.size / 1024).toFixed(1)} KB`, tags: [], content, uploaded: true, approved: false }]);
        count++;
