    const stopwords = ['welche', 'welchen', 'welcher', 'finde', 'kann', 'soll', 'sind', 'eine', 'einen', 'habe', 'wird', 'mein', 'meine', 'oder', 'sich', 'dass', 'bitte', 'hier', 'wieviel', 'noch', 'viel', 'muss', 'machen', 'sollte', 'wenn', 'nach', 'einem', 'gibt', 'haben', 'können', 'steht', 'steht'];
    const meaningful = tokens.filter(t => !stopwords.includes(t));
